using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  internal static string CapturedChord(Key key,ModifierKeys modifiers){if(key==Key.System||key==Key.LeftCtrl||key==Key.RightCtrl||key==Key.LeftAlt||key==Key.RightAlt||key==Key.LeftShift||key==Key.RightShift||key==Key.LWin||key==Key.RWin)return null;var native=(System.Windows.Forms.Keys)KeyInterop.VirtualKeyFromKey(key);var parts=new List<string>();if((modifiers&ModifierKeys.Control)!=0)parts.Add("Ctrl");if((modifiers&ModifierKeys.Shift)!=0)parts.Add("Shift");if((modifiers&ModifierKeys.Alt)!=0)parts.Add("Alt");parts.Add(ProfileHotkey.KeyLabel(native));return ProfileHotkey.Parse(String.Join(" + ",parts)).ToString();}
  static readonly DependencyProperty CaptureCancelProperty=DependencyProperty.RegisterAttached("CaptureCancel",typeof(Func<bool>),typeof(MainWindow));
  internal static bool CancelChordCapture(DependencyObject focused){var cancel=focused==null?null:focused.GetValue(CaptureCancelProperty) as Func<bool>;return cancel!=null&&cancel();}
  Button CaptureButton(string chord){var button=new Button{Content=String.IsNullOrEmpty(chord)?"Назначить":chord,Style=(Style)FindResource("PickerAction"),Background=(System.Windows.Media.Brush)FindResource("Field"),HorizontalContentAlignment=HorizontalAlignment.Left,Padding=new Thickness(10,4,10,4)};button.Tag=chord;bool listening=false;button.Name="hotkeyCapture";Action cancel=()=>{listening=false;button.Content=button.Tag??"Не назначена";};button.SetValue(CaptureCancelProperty,new Func<bool>(()=>{if(!listening)return false;cancel();return true;}));button.Click+=(s,e)=>{listening=true;button.Content="Нажмите сочетание…";button.Focus();};button.PreviewKeyDown+=(s,e)=>{if(!listening)return;e.Handled=true;Key key=e.Key==Key.System?e.SystemKey:e.Key;if(key==Key.Escape){cancel();return;}if((key==Key.Back||key==Key.Delete)&&Keyboard.Modifiers==ModifierKeys.None){button.Tag=null;button.Content="Не назначена";listening=false;return;}try{string captured=CapturedChord(key,Keyboard.Modifiers);if(captured!=null){button.Tag=captured;button.Content=captured;listening=false;}}catch(Exception ex){status.Text=ex.Message;}};return button;}
  Task HotkeysDialog(){return EditHotkeys(null);}
  Task ProfileHotkeyDialog(ZapretProfile profile){return EditHotkeys(profile.Id);}
  async Task EditHotkeys(string profileId){var beforeGlobal=session.State.GlobalHotkeys==null?null:new Dictionary<string,string>(session.State.GlobalHotkeys);var beforeProfiles=session.State.ZapretProfiles.ToDictionary(p=>p.Id,p=>p.Hotkey);var ids=profileId==null?new[]{"@zapret","@telegram","@warp","@tun"}:new[]{profileId};var window=Dialog(profileId==null?"Глобальные горячие клавиши":"Горячая клавиша профиля",700,profileId==null?470:280);var panel=new DockPanel{Margin=new Thickness(20)};var forms=new StackPanel();forms.Children.Add(Text("Нажмите поле, затем сочетание Ctrl / Shift / Alt с обычной клавишей. Backspace снимает назначение; Escape отменяет ввод."));var edits=new Dictionary<string,Button>();foreach(string id in ids){string chord=null,label=id=="@zapret"?"Zapret":id=="@telegram"?"Telegram WS":id=="@warp"?"WARP":id=="@tun"?"TUN":session.State.ZapretProfiles.First(p=>p.Id==id).Name;if(id.StartsWith("@")){if(session.State.GlobalHotkeys!=null)session.State.GlobalHotkeys.TryGetValue(id,out chord);}else chord=session.State.ZapretProfiles.First(p=>p.Id==id).Hotkey;var capture=CaptureButton(chord);edits[id]=capture;forms.Children.Add(Field(label,capture));}
   var actions=Toolbar(Button("Сохранить",()=>{try{var staged=edits.ToDictionary(p=>p.Key,p=>p.Value.Tag==null?null:Convert.ToString(p.Value.Tag));foreach(var item in staged){var error=hotkeys.Set(item.Key,item.Value);if(error!=null){RegisterHotkeys();throw new InvalidOperationException(error);}}if(session.State.GlobalHotkeys==null)session.State.GlobalHotkeys=new Dictionary<string,string>();foreach(var item in staged){if(item.Key.StartsWith("@")){if(item.Value==null)session.State.GlobalHotkeys.Remove(item.Key);else session.State.GlobalHotkeys[item.Key]=item.Value;}else session.State.ZapretProfiles.First(p=>p.Id==item.Key).Hotkey=item.Value;}window.DialogResult=true;}catch(Exception ex){Notice(ex.Message,"Горячие клавиши");}}),Button("Отмена",()=>window.DialogResult=false));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(forms);window.Content=panel;if(window.ShowDialog()==true){try{await session.Save();}catch{session.State.GlobalHotkeys=beforeGlobal;foreach(var p in session.State.ZapretProfiles)if(beforeProfiles.ContainsKey(p.Id))p.Hotkey=beforeProfiles[p.Id];RegisterHotkeys();throw;}if(current=="Zapret & Byetube")RefreshAfterOperation("Zapret");}}
 }
}
